UPDATE tb_sku
category_id = #{po.categoryId}, name = #{po.name}, description = #{po.description}, price = #{po.price}, market_price = #{po.marketPrice}, stock = #{po.stock}, stock_threshold = #{po.stockThreshold}, fake_sales = #{po.fakeSales}, store_stock = #{po.storeStock}, type = #{po.type}, product_type = #{po.productType}, images = #{po.images}, spec = #{po.spec}, delivery_methods = #{po.deliveryMethods}, sort = #{po.sort}, updated_at = CURRENT_TIMESTAMP
WHERE id = #{po.id} AND shop_id = #{shopId}

mapper.sql:
WHERE shop_id = #{shopId}

    AND name LIKE '%' || #{name} || '%'


    AND product_type = #{productType}


    AND type = #{type}


    AND status = #{status}


    AND category_id = #{categoryId}


    AND (

        delivery_methods LIKE '%' || #{dm} || '%'

    )

mapper.select:
SELECT * FROM tb_sku

ORDER BY sort DESC, id DESC
LIMIT #{size} OFFSET #{offset}

SELECT *, (sales + COALESCE(fake_sales, 0)) AS display_sales FROM tb_sku

ORDER BY ${sortBy.sql}
LIMIT #{size} OFFSET #{offset}
